export const directionVector=direction=>({up:{x:0,y:-1},down:{x:0,y:1},left:{x:-1,y:0},right:{x:1,y:0}}[direction]);
export function isInAttackArc(actor,target,range=84){const dx=target.x-actor.x,dy=target.y-actor.y,d=Math.hypot(dx,dy);if(d>range)return false;if(d<24)return true;const facing=directionVector(actor.direction);return (dx*facing.x+dy*facing.y)/d>.15;}
export class PunchAttack{
 constructor(scene,combo){this.scene=scene;this.combo=combo;}
 attack(actor,finisher=false){const s=this.scene;if(actor.ko||actor.actionLocked||s.now<actor.stunUntil||s.now-actor.lastAttack<(finisher?200:330))return false;actor.lastAttack=s.now;actor.state='ATTACK';if(!finisher)this.combo.push(actor.id,s.now);const v=directionVector(actor.direction),x=actor.x+v.x*44,y=actor.y+v.y*44-22;const ring=s.add.ellipse(x,y,finisher?115:65,finisher?65:38,finisher?0xf7d84a:0xfff2c7,.28).setStrokeStyle(3,finisher?0xf7d84a:0xfff2c7).setDepth(actor.y+8);s.tweens.add({targets:ring,alpha:0,scale:1.5,duration:160,onComplete:()=>ring.destroy()});let hits=0;const damage=Math.round(actor.stats.strength*(finisher?1.8:1));for(const enemy of s.enemies)if(!enemy.ko&&isInAttackArc(actor,enemy,finisher?120:87)&&s.map.clearLine(actor.x,actor.y,enemy.x,enemy.y)){enemy.hit(damage,actor);hits++;}for(const crate of s.crates)if(!crate.destroyed&&isInAttackArc(actor,crate,80)&&s.map.clearLine(actor.x,actor.y,crate.x,crate.y)){crate.hit(damage,actor);hits++;}if(hits){s.fx?.hit(x,y,finisher);actor.special=Math.min(100,actor.special+hits*12);s.audio.effect('hit');s.audio.say(actor.id,'attack',0);if(finisher)s.toast('COMBO · '+(actor.id==='click'?'Gancio d’acciaio':'Impulso tattico'));}return true;}
}
